module.exports = function(RED) {
    "use strict";

    function DeviceServiceNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;

        this.name = n.name;
        this.deviceType = n.deviceType;       // deviceTypeId
        this.deviceTypeName = n.deviceTypeName; // 新增: 保存设备类型名称
        this.deviceService = n.deviceService; // deviceServiceId
        this.deviceServiceName = n.deviceServiceName; // 新增: 保存功能名称

        try {
            // 如果配置界面传过来的是 JSON 字符串，则解析它
            this.params = n.nodeParams ? JSON.parse(n.nodeParams) : [];
        } catch (err) {
            // 如果解析出错（例如格式不对），设为空数组并打印错误
            this.params = [];
            node.error("解析参数列表失败: " + err);
        }

        setImmediate(function() {
            node.emit("input", {});
        });

        this.on("input", function(msg, send, done) {
            msg = msg || {};
            msg.name = node.name;
            msg.type = node.type;

            msg.deviceTypeId = node.deviceType;
            msg.deviceTypeName = node.deviceTypeName;

            msg.deviceServiceId = node.deviceService;
            msg.deviceServiceName = node.deviceServiceName;

            msg.deviceParams = node.params; 

            // msg.deviceId = node.deviceId;

            send(msg);
            done();
        });
    }

    RED.nodes.registerType("Device Service", DeviceServiceNode);
};